   619	\section{Generalized Pauli observables}
   620	% Paper label sec:generalized-pauli kept for cross-reference fidelity.
   621	\label{sec:generalized-pauli}
   622	
   623	\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
   624		\lean{MIPStarRE.QPBT.primeTauShift, MIPStarRE.QPBT.primeTauPhase}
   625		\lean{MIPStarRE.QPBT.primeTauObservable, MIPStarRE.QPBT.primePauliFourier}
   626		\lean{MIPStarRE.QPBT.primePauliVec, MIPStarRE.QPBT.primePauliProj}
   627		\lean{MIPStarRE.QPBT.primePauliVec_orthonormal}
   628		\lean{MIPStarRE.QPBT.primeTauObservable_mulVec_primePauliVec}
   629		\lean{MIPStarRE.QPBT.primePauliProj_isProj, MIPStarRE.QPBT.sum_primePauliProj_eq_one}
   630		\leanok
   631		\uses{def:subfield-trace, def:lin-reg}
   632		Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
   633		observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
   634		\begin{equation}\label{eq:pauli-fp}
   635			\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
   636			\qquad \text{and} \qquad
   637			\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
   638		\end{equation}
   639		for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
   640		\emph{generalized Pauli observables over $\F_q$} are the unitaries on
   641		$\C^{\F_q}$
   642		\[
   643			\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
   644			\qquad \text{and} \qquad
   645			\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
   646		\]
   647		for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
   648		(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
   649		the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
   650		signs. All the $\tau^X$ operators commute with one another, as do all the
   651		$\tau^Z$ operators. Their common eigenbases consist of the vectors
   652		$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
   653		\[
   654			\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
   655			\omega^{-\tr(ej)} \ket{j}\;, \qquad
   656			\ket{e_Z} = \ket{e}\;;
   657		\]
   658		the Fourier transform
   659		\begin{equation}\label{eq:fourier-f}
   660			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
   661			\omega^{-\tr(ab)} \ket{a}\bra{b}
   662		\end{equation}
   663		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
   664		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
   665		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
   666		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
   667		\[
   668			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
   669			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
   670		\]
   671		for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
   672		The distinction between the general prime-characteristic definitions and
   673		the characteristic-two specializations used by the Pauli basis test is
   674		documented in \cite{gap:qpbt_characteristic-two-pauli-scope}.
   675	\end{definition}
   676	
   677	\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
   678		\lean{MIPStarRE.QPBT.primeTauObservable_mul}
   679		\lean{MIPStarRE.QPBT.primeTauObservable_pow}
   680		\lean{MIPStarRE.QPBT.primeTauObservable_pow_char}
   681		\lean{MIPStarRE.QPBT.primeTauObservable_isUnitary}
   682		\lean{MIPStarRE.QPBT.primeTauObservable_eigenvalue_pow_char}
   683		\lean{MIPStarRE.QPBT.primeTauObservable_X_mul_Z}
   684		\leanok
   685		\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
   686		Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
   687		\begin{enumerate}
   688			\item For all $a, a' \in \F_q$ and $b \in \F_p$,
   689			      \begin{equation}\label{eq:pauli-product-power}
   690				      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
   691				      \qquad \text{and} \qquad
   692				      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
   693			      \end{equation}
   694			      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$. By the explicit
   695			      definitions each $\tau^W(a)$ is unitary, and its eigenvalues are
   696			      $p$-th roots of unity.
   697			\item For all $a, b \in \F_q^n$,
   698			      % Paper equation label kept on the display it names.
   699			      \begin{equation}\label{eq:twisted-fq}
   700				      \tau^X(a)\, \tau^Z(b)
   701				      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
   702			      \end{equation}
   703			      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
   704			      $q = p$, $n = 1$ reads
   705			      \begin{equation}\label{eq:twisted-fp}
   706				      \sigma^X(a)\, \sigma^Z(b)
   707				      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
   708				      \qquad \text{for all } a, b \in \F_p\;.
   709			      \end{equation}
   710		\end{enumerate}
   711	\end{lemma}
   712	\begin{proof}
   713		\leanok
   714		\uses{def:generalized-pauli, def:subfield-trace}
   715		All identities are verified on computational basis states. For the product
   716		relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
   717		$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
   718		combine by $\F_q$-linearity of the trace, and the power relation follows by
   719		iterating. For the scalar twisted commutation,
   720		$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
   721		$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
   722		\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
   723		follows by applying the scalar relation factor by factor and summing the
   724		exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
   725		trace is the identity map, which gives \eqref{eq:twisted-fp}.
   726	\end{proof}
   727	
   728	\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
   729		\lean{MIPStarRE.QPBT.ffChar_dotProduct_submodule_expect_eq_zero}
   730		\leanok
   731		\uses{def:dot-product-orthogonal, def:subfield-trace}
   732		Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
   733		$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
   734		$v \notin V^\perp$,
   735		\[
   736			\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
   737		\]
   738		where the expectation is over a uniformly random vector $\bu$ in $V$.
   739	\end{lemma}
   740	\begin{proof}
   741		\leanok
   742		This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
   743		the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
   744		on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
   745		shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
   746		for the expectation, translation invariance of the uniform distribution on
   747		$V$ gives
   748		$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
   749		= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
   750		forces $C = 0$.
   751	\end{proof}
   752	
   753	\begin{lemma}[Fourier expansion of Pauli observables]\label{lem:pauli-observable-expansion}
   754		\lean{MIPStarRE.QPBT.primeTauObservable_eq_sum_primePauliProj}
   755		\lean{MIPStarRE.QPBT.primePauliProj_eq_avg_primeTauObservable}
   756		\leanok
   757		\uses{def:generalized-pauli, def:subfield-trace}
   758		For every integer $n \ge 1$, all $W \in \{X, Z\}$, and all $a \in \F_q^n$,
   759		% Paper equation label kept on the display it names.
   760		\begin{equation}\label{eq:pauli-obs-proj}
   761			\tau^W(a) = \sum_{b \in \F_q^n} \omega^{\tr(a \cdot b)}\, \tau^W_b\;,
   762		\end{equation}
   763		and conversely
   764		\begin{equation}\label{eq:pauli-inversion-0}
   765			\E_{\ba \sim \F_q^n}\, \omega^{-\tr(\ba \cdot b)}\, \tau^W(\ba)
   766			= \sum_{b' \in \F_q^n} \E_{\ba \sim \F_q^n}\,
   767			\omega^{\tr(\ba \cdot (b' - b))}\, \tau^W_{b'}
   768			= \tau^W_b\;.
   769		\end{equation}
   770		The source scope and the binary specialization of these identities are
   771		recorded in \cite{gap:qpbt_characteristic-two-pauli-scope}.
   772	\end{lemma}
   773	\begin{proof}
   774		\leanok
   775		\uses{def:generalized-pauli, lem:cancellation}
   776		Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
   777		$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
   778		definition, and for $W = X$ it follows from the single-qudit computation
   779		$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
   780		Expanding $\tau^W(a)$ in the orthonormal eigenbasis
   781		$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
   782		substitute the first display and exchange the order of summation; by
   783		Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
   784		$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
   785		it equals $1$.
   786	\end{proof}
   787	
   788	Since only admissible field sizes $q = 2^k$ arise in the Pauli basis test, the
   789	maximally entangled state $\ket{\mathrm{EPR}_q}$ and the qudit Pauli
   790	projectors are isomorphic to tensor products of qubit EPR states
   791	$\ket{\mathrm{EPR}_2}$ and qubit Pauli projectors. This is the content of the
   792	next lemma, which is what allows the Pauli basis test to self-test Pauli
   793	observables and maximally entangled states over \emph{qubits}
   794	(Chapter~\ref{chap:qpbt-test}).
   795	
   796	\begin{lemma}[Qudit-to-qubit isomorphism]\label{lem:pauli-binary}
   797		\lean{MIPStarRE.QPBT.qubitPauliProj, MIPStarRE.QPBT.exists_qubitIsometry}
   798		\leanok
   799		\uses{def:admissible-size, def:subfields-kappa, def:binary-representation,
   800			def:generalized-pauli, def:EPR}
   801		For all admissible field sizes $q = 2^k$ and integers $L \ge 0$, there
   802		exists an isomorphism $\phi : (\C^q)^{\ot L} \to (\C^2)^{\ot Lk}$ such that
   803		\begin{equation}\label{eq:epr-q-to-epr-2}
   804			\phi \ot \phi\, \ket{\mathrm{EPR}_q}^{\ot L}
